package com.governai.audit;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/audit-events")public class AuditController{private final AuditEventRepository events;public AuditController(AuditEventRepository events){this.events=events;}@GetMapping("/decision/{decisionId}")public List<AuditEventResponse> decisionEvents(@PathVariable UUID decisionId){return events.findByDecisionRequestIdOrderByCreatedAtAsc(decisionId).stream().map(AuditEventResponse::from).toList();}@GetMapping("/organization/{organizationId}")public List<AuditEventResponse> organizationEvents(@PathVariable UUID organizationId){return events.findByOrganizationIdOrderByCreatedAtDesc(organizationId).stream().map(AuditEventResponse::from).toList();}}
